+  ANTHROPIC_API_KEY: "test-key",
+  WORKSPACES_ENABLED: true,
+}));
+
+let currentAuthUid: string | null = "owner-uid";
+jest.mock("@/lib/auth/resolveRequestIdentity", () => ({
